--- /dev/null
+++ b/src/applet/powersupplybatteries.cpp
@@ -0,0 +1,74 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include "powersupplybatteries.h"
+
+#include <Solid/Battery>
+#include <Solid/DeviceNotifier>
+
+PowerSupplyBatteries::PowerSupplyBatteries(QObject *parent)
+    : QObject(parent)
+{
+    connect(Solid::DeviceNotifier::instance(), &Solid::DeviceNotifier::deviceAdded, this, [this](const QString &udi) {
+        addDevice(udi);
+        update();
+    });
+    connect(Solid::DeviceNotifier::instance(), &Solid::DeviceNotifier::deviceRemoved, this, [this](const QString &udi) {
+        removeDevice(udi);
+        update();
+    });
+
+    const QList<Solid::Device> devices = Solid::Device::listFromType(Solid::DeviceInterface::Battery);
+    for (const Solid::Device &device : devices) {
+        addDevice(device.udi());
+    }
+    update();
+}
+
+QVariantMap PowerSupplyBatteries::percentages() const
+{
+    return m_percentages;
+}
+
+void PowerSupplyBatteries::addDevice(const QString &udi)
+{
+    if (m_devices.contains(udi)) {
+        return;
+    }
+
+    Solid::Device device(udi);
+    Solid::Battery *battery = device.as<Solid::Battery>();
+    if (!battery || battery->isPowerSupply()) {
+        return;
+    }
+
+    m_devices.insert(udi, device);
+    connect(battery, &Solid::Battery::chargePercentChanged, this, &PowerSupplyBatteries::update);
+    connect(battery, &Solid::Battery::presentStateChanged, this, &PowerSupplyBatteries::update);
+}
+
+void PowerSupplyBatteries::removeDevice(const QString &udi)
+{
+    m_devices.remove(udi);
+}
+
+void PowerSupplyBatteries::update()
+{
+    QVariantMap percentages;
+    for (const Solid::Device &device : std::as_const(m_devices)) {
+        const Solid::Battery *battery = device.as<Solid::Battery>();
+        if (battery && battery->isPresent() && !battery->serial().isEmpty()) {
+            percentages.insert(battery->serial().toLower(), battery->chargePercent());
+        }
+    }
+
+    if (percentages != m_percentages) {
+        m_percentages = percentages;
+        Q_EMIT percentagesChanged();
+    }
+}
+
+#include "moc_powersupplybatteries.cpp"
diff --git a/src/applet/powersupplybatteries.h b/src/applet/powersupplybatteries.h
new file mode 100644
