--- /dev/null
+++ b/src/applet/powersupplybatteries.h
@@ -0,0 +1,42 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <QHash>
+#include <QObject>
+#include <QVariantMap>
+
+#include <Solid/Device>
+
+#include <qqmlregistration.h>
+
+// Battery levels of devices that report them through the kernel (like game
+// controllers) instead of BlueZ, keyed by lowercase Bluetooth address.
+class PowerSupplyBatteries : public QObject
+{
+    Q_OBJECT
+    QML_ELEMENT
+    QML_SINGLETON
+
+    Q_PROPERTY(QVariantMap percentages READ percentages NOTIFY percentagesChanged FINAL)
+
+public:
+    explicit PowerSupplyBatteries(QObject *parent = nullptr);
+
+    QVariantMap percentages() const;
+
+Q_SIGNALS:
+    void percentagesChanged();
+
+private:
+    void addDevice(const QString &udi);
+    void removeDevice(const QString &udi);
+    void update();
+
+    QHash<QString, Solid::Device> m_devices;
+    QVariantMap m_percentages;
+};
